service.method:

      MERGE INTO SUSMT
	       USING ( SELECT ${USER_ID} USER_ID
			     ) M
	          ON ( SUSMT.USER_ID   = M.USER_ID
	          	  AND SUSMT.HOUSE_CODE = ${session.HOUSE_CODE}
	          	  AND SUSMT.COMPANY_CODE = ${COMPANY_CODE}
	          	 )
	 WHEN MATCHED 
	 THEN 
      UPDATE  
       SET COMPANY_CODE   = ${COMPANY_CODE}
	     , PLANT_CODE     = ${PLANT_CODE}
	     , CHANGE_DATE    = ${current.DATE}
	     , CHANGE_TIME    = ${current.TIME}
	     , DEPT           = ${DEPT}
	     , USER_NAME_LOC  = ${USER_NAME_LOC}
	     , USER_NAME_ENG  = ${USER_NAME_ENG}
	     , LANGUAGE       = ${LANGUAGE}
	     , TIME_ZONE      = ${TIME_ZONE}
	     , EMAIL          = ${EMAIL}
	     , COUNTRY        = ${COUNTRY}
	     , STATE          = ${STATE}
	     , EMPLOYEE_NO    = ${EMPLOYEE_NO}
	     , SIGN_STATUS    = 'A'
	     , POSITION       = ${POSITION}
	     , WORK_TYPE      = ${WORK_TYPE}
	     , USER_TYPE      = ${USER_TYPE}
	     , THEME          = ${THEME}
	     , CHANGE_USER_ID = ${session.ID}
	     , DATE_FORMAT    = ${DATE_FORMAT}


	     ,PASSWORD        = ${PASSWORD_1}
	     ,PW_RESET_FLAG   = 'Y'
	     ,PW_RESET_DATE   = ${current.DATE}  


	WHEN NOT MATCHED 
    THEN
     	INSERT (
				  HOUSE_CODE
				, USER_ID
				, ADD_DATE
				, ADD_TIME
				, ADD_USER_ID
				, CHANGE_DATE
				, CHANGE_TIME
				, CHANGE_USER_ID
				, COMPANY_CODE
				, PLANT_CODE
				, USER_NAME_LOC
				, USER_NAME_ENG
				, DEPT
				, POSITION
				, LANGUAGE
				, MENU_TYPE
				, TIME_ZONE
				, EMAIL
				, COUNTRY
				, STATE
				, EMPLOYEE_NO
				, SIGN_STATUS
				, WORK_TYPE
				, MENU_PROFILE_CODE
				, USER_TYPE
				, PASS_CHECK_CNT
				, DEL_FLAG
				, LAST_LOGIN_DATE
				, LAST_LOGIN_TIME
				, LAST_LOGIN_IP
				, THEME
				, DATE_FORMAT
				, CTRL_CODE


			    , PASSWORD
			    , PW_RESET_FLAG
			    , PW_RESET_DATE


		) VALUES (
				  ${session.HOUSE_CODE}
				, ${USER_ID}
				, ${current.DATE}
				, ${current.TIME}
				, ${USER_ID}
				, ${current.DATE}
				, ${current.TIME}
				, ${USER_ID}
				, ${COMPANY_CODE}
				, ${PLANT_CODE}
				, ${USER_NAME_LOC}
				, ${USER_NAME_ENG}
				, ${DEPT}
				, ${POSITION}
				, ${LANGUAGE}
				, ${MENU_TYPE}
				, ${TIME_ZONE}
				, ''
				, ${COUNTRY}
				, ${STATE}
				, ${EMPLOYEE_NO}
				, 'A'
				, 'Z'
				, ${MENU_PROFILE_CODE}
				, ${USER_TYPE}
				, '0'
				, 'N'
				, ${current.DATE}
				, ${current.TIME}
				, ${LAST_LOGIN_IP}
				, ${THEME}
				, ${DATE_FORMAT}
				, ${CTRL_CODE}


			    , ${PASSWORD_1}
			    , 'Y'
			    , ${current.DATE}


				);


    	UPDATE SUSMT
      	   SET CHANGE_DATE    = ${current.DATE},
	           CHANGE_TIME    = ${current.TIME},
	           CHANGE_USER_ID = ${session.ID},
	           USER_NAME_LOC  = ${USER_NAME_LOC},
	           USER_NAME_ENG  = ${USER_NAME_ENG}


		  ,PASSWORD = ${PASSWORD_1}
		  ,PW_RESET_FLAG = 'Y'
		  ,PW_RESET_DATE = ${current.DATE}  


      WHERE USER_ID  = ${session.ID}
        AND HOUSE_CODE = ${session.HOUSE_CODE}


		MERGE INTO SADDR
		USING ( SELECT ${USER_ID} USER_ID ) M
		   ON ( SADDR.HOUSE_CODE	= ${session.HOUSE_CODE}
		   	AND SADDR.CODE_NO   	= M.USER_ID 
		   	AND SADDR.CODE_TYPE   	= 'USER'
		   	  )
		 WHEN MATCHED
		 THEN 
			  UPDATE 
	      	     SET CHANGE_DATE    = ${current.DATE},
		             CHANGE_TIME    = ${current.TIME},
		             CHANGE_USER_ID = ${session.ID},
		             EMAIL          = ${EMAIL},
		             PHONE_NO1      = ${PHONE_NO1},
		             PHONE_NO2      = ${PHONE_NO2},
		             FAX_NO         = ${FAX_NO}
	      WHEN NOT MATCHED 
	      THEN
	     	  INSERT (
     	              HOUSE_CODE
					, CODE_NO
					, CODE_TYPE
					, ZIP_CODE
					, PHONE_NO1
					, FAX_NO
					, HOMEPAGE
					, ADDRESS_LOC
					, ADDRESS_ENG
					, CEO_NAME_LOC
					, CEO_NAME_ENG
					, EMAIL
					, ZIP_BOX_NO
					, PHONE_NO2
					, ADD_DATE
					, ADD_TIME
					, ADD_USER_ID
					, CHANGE_DATE
					, CHANGE_TIME
					, CHANGE_USER_ID
					, DEL_FLAG
					, ADDRESS_TEXT
			) VALUES (
					  ${session.HOUSE_CODE}
					, ${USER_ID}
					, 'USER'
					, ${ZIP_CODE}
					, ${PHONE_NO1}
					, ${FAX_NO}
					, ${HOMEPAGE}
					, ${ADDRESS_LOC}
					, ${ADDRESS_ENG}
					, ${CEO_NAME_LOC}
					, ${CEO_NAME_ENG}
					, ${EMAIL}
					, ${ZIP_BOX_NO}
					, ${PHONE_NO2}
					, ${current.DATE}
				    , ${current.TIME}
				    , ${USER_ID}
				    , ${current.DATE}
				    , ${current.TIME}
				    , ${USER_ID}
				    , 'N'
				    , ${ADDRESS_TEXT}			    
		);


INSERT INTO SADDR (
				  HOUSE_CODE
				, CODE_NO
				, CODE_TYPE
				, ZIP_CODE
				, PHONE_NO1
				, FAX_NO
				, HOMEPAGE
				, ADDRESS_LOC
				, ADDRESS_ENG
				, CEO_NAME_LOC
				, CEO_NAME_ENG
				, EMAIL
				, ZIP_BOX_NO
				, PHONE_NO2
				, ADD_DATE
				, ADD_TIME
				, ADD_USER_ID
				, CHANGE_DATE
				, CHANGE_TIME
				, CHANGE_USER_ID
				, DEL_FLAG
				, ADDRESS_TEXT
		) VALUES (
				  ${session.HOUSE_CODE}
				, ${USER_ID}
				, 'USER'
				, ${ZIP_CODE}
				, ${PHONE_NO1}
				, ${FAX_NO}
				, ${HOMEPAGE}
				, ${ADDRESS_LOC}
				, ${ADDRESS_ENG}
				, ${CEO_NAME_LOC}
				, ${CEO_NAME_ENG}
				, ${EMAIL}
				, ${ZIP_BOX_NO}
				, ${PHONE_NO2}
				, ${current.DATE}
			    , ${current.TIME}
			    , ${USER_ID}
			    , ${current.DATE}
			    , ${current.TIME}
			    , ${USER_ID}
			    , 'N'
			    , ${ADDRESS_TEXT}			    
)
